export type SecretMap = Partial<{ [key in string]: string }>
export type ServiceCapabilities = { requires_server_vad: boolean; prefers_auto_gain: boolean; prefers_noise_reduction: boolean; max_concurrent_streams: number }
export type ServiceDiscoveryInfo = { present: boolean; state_dir: string; port: number | null; pid: number | null; protocol_version: number | null; token_fingerprint: string | null; pid_alive: boolean; port_open: boolean }
export type ServiceHealthInfo = { status: string; version: string; engine_version: string; protocol_version: number; uptime_ms: number; ready: boolean }
export type ServiceProbeReport = { alive: boolean; token_present: boolean; health: ServiceHealthInfo | null; health_error: string | null; status: ServiceStatusInfo | null; status_error: string | null }
export type ServiceRotateResult = { id: string; name: string; 
/**
 * Plaintext, returned exactly once by the daemon. Held by the GUI in
 * memory only (never persisted).
 */
token: string; prefix: string; created_at: string }
export type ServiceStartResult = { already_running: boolean; info: ServiceDiscoveryInfo; 
/**
 * True when this spawn captured a first-run token from stdout. The token
 * itself stays in memory; the GUI never sees it through this channel.
 */
token_captured: boolean }
export type ServiceStatusInfo = { mode: string; bind: string; active_model_id: string | null; model_state: string; backend: string | null; active_session_id: string | null; active_sessions: number; max_realtime_factor: number | null; lease_held: boolean; capabilities: ServiceCapabilities }
export type ServiceStopResult = { stopped: boolean; pid: number | null; detail: string }
export type ShortcutBinding = { id: string; name: string; description: string; default_binding: string; current_binding: string }
export type SoundTheme = "marimba" | "pop" | "custom"
/**
 * Phase of the streaming overlay card, emitted to drive its UI state.
 */
export type StreamPhase = 
/**
 * Receiving audio / live text (or waiting for the stream to begin). Rust
 * does not emit this today; the frontend starts in this phase and Rust only
 * emits transitions away from it.
 */
"listening" | 
/**
 * Finalizing or post-processing — show a spinner.
 */
"working"
/**
 * Emitted to switch the streaming overlay to a working spinner.
 */
export type StreamPhaseEvent = { phase: StreamPhase; 
/**
 * Present only when `phase` is `Working`.
 */
kind?: StreamWorkKind | null }
/**
 * Live transcription snapshot emitted to the overlay during a streaming run.
 * `committed` is the append-only, flicker-free prefix; `tentative` is the
 * volatile suffix the model may still rewrite.
 */
export type StreamTextEvent = { committed: string; tentative: string }
/**
 * Semantic kind of "working" phase, used to localize the spinner label.
 */
export type StreamWorkKind = "transcribing" | "polishing"
/**
 * Tailscale network information for this device.
 */
export type TailscaleInfo = { 
/**
 * IPv4 Tailscale address (100.x.x.x), if available.
 */
ip: string | null; 
/**
 * MagicDNS hostname (e.g. `my-mac.tailxxxxx.ts.net`), if available.
 */
dns: string | null; 
/**
 * True when Tailscale appears to be installed and running.
 */
available: boolean }
